package driver

import (
	"io"
	"os"
	"path/filepath"
	"time"

	"kigumi/internal/syntax"
	"kigumi/internal/token"
)

// Package is one directory of .kg files; Path is the canonical import path relative to the module root, with std packages carrying the "std/" prefix.
type Package struct {
	Path  string
	Dir   string
	Files []*syntax.Tree
	// Std marks declaration stubs: bodiless functions are allowed there.
	Std bool
	// Header marks a package generated by a Header import; like Std, it stays in an explicit entry's diagnostic scope even when unimported.
	Header bool
	// Module is the dependency the package came from; "" for the module
	// being built.
	Module string
}

// Module is a module root plus the std stubs it can import.
type Module struct {
	Root string
	// Name is the module name from mod.kg; it prefixes the import paths of
	// the module's own packages. "" for a manifest-less directory.
	Name  string
	Entry string
	// ExplicitEntry marks that the caller picked one root rather than the whole module; it narrows checking to that entry's build scope.
	ExplicitEntry bool
	overlay       map[string][]byte
	// diagsReported marks that reportDiagnostics already wrote m's diagnostics once, so a build's later compile() call skips the write shared.Load made.
	diagsReported bool
	// FileStore numbers every parsed source so diagnostics can point
	// across files.
	FileStore *token.SourceStore
	stats     Stats
	// lastAnalysis is the most recent Analyze result, for a post-build
	// report (ResourceReport) that would otherwise need to re-lower the module.
	lastAnalysis *Analysis
	Packages     map[string]*Package
	// Order lists package paths sorted for deterministic iteration.
	Order []string
	// Links and Sources collect the C libraries and sources of the module
	// and its dependencies, search paths and sources made absolute.
	Links   []Link
	Sources []string
	// Manifest is mod.kg, or the leading records of the script.
	Manifest ModFile
	// Selected is what minimal version selection chose for each dependency.
	Selected map[string]Require
	// ScriptFile is the root-relative entry that carried the manifest.
	ScriptFile string
	// Violations are release-policy findings from loading (a local replacement,
	// an unresolved native Link); EvaluateRelease classifies each under a BuildPolicy.
	Violations []Violation
	local      Local
	target     Target
	// deny, ceiling and artifactName carry an artifact's declared
	// availability (LoadOptions) through to semModule (check.go).
	deny         []string
	ceiling      string
	artifactName string
	// explicitZig is $KIGUMI_ZIG (LoadOptions.ZigPath), read only by
	// internal/cli; ResolveZig tries it before PATH.
	explicitZig string
	// Carry LoadOptions' same-named fields to ResolveZig's on-demand fetch.
	zigHome      string
	zigIndexURL  string
	zigPublicKey string
	offline      bool
	zigNotice    io.Writer
	verifyPasses bool
	lowerAll     bool
	fileOrder    func(names []string)
	compiler     CompilerOptions
	index        *pkgIndex
	idxStats     IndexStats
	rootDirs     []string
	rootImports  []string
	allPackages  bool
	allOwn       bool
	// deferred marks a load whose reachable packages are not parsed yet (ensureParsed).
	deferred bool
	loadErr  error
	pkgCache *packageCache
	test     bool
	settled  *settledCheck
	// keyEntry and keyExplicit are the entry as loaded; semModule may fill m.Entry in later.
	keyEntry    string
	keyExplicit bool
	cancel      func() bool
	pkgStatus   []PackageStatus
	unitCheck   bool
	lazyStd     bool
	unitStats   UnitStats
}

// LoadModule indexes every package under root and the std stubs, then parses the packages the root set reaches. Parse diagnostics stay on each Tree; loading itself only fails on I/O.
func LoadModule(root string, opts LoadOptions) (*Module, error) {
	m := &Module{Root: root, Entry: opts.Entry, ExplicitEntry: opts.Entry != "", overlay: opts.Overlay, Packages: map[string]*Package{}, local: Local{Replaces: map[string]string{}}, target: opts.Target, deny: opts.Deny, ceiling: opts.Ceiling, artifactName: opts.ArtifactName, explicitZig: opts.ZigPath, zigHome: opts.ZigHome, zigIndexURL: opts.ZigIndexURL, zigPublicKey: opts.ZigPublicKey, offline: opts.Offline, zigNotice: opts.ZigNotice, verifyPasses: opts.VerifyPasses, rootDirs: opts.RootDirs, rootImports: opts.RootImports, allPackages: opts.AllPackages, allOwn: opts.AllOwnPackages, deferred: opts.DeferParse, unitCheck: opts.UnitCheck, lazyStd: opts.LazyStd, test: opts.Test, keyEntry: opts.Entry, keyExplicit: opts.Entry != "", fileOrder: opts.FileOrder, compiler: opts.Compiler}
	m.index = newPkgIndex(opts.PackageCache, root, opts.Compiler, time.Now)
	m.pkgCache = newPackageCache(opts.PackageCache)
	if m.target.OS == "" {
		m.target = m.compiler.HostOrAmbient()
	}
	if m.target.Unverified() {
		m.Violations = append(m.Violations, unverifiedTargetViolation(m.target.Triple))
	}
	mf, hasMod, err := ReadModFile(root)
	if err != nil {
		return nil, err
	}
	m.Name, m.Manifest = mf.Name, mf
	skip := func(dir string) bool { return skipDir(dir, opts.StdRoot) || IsModuleRoot(dir) }
	if err := m.indexTree(root, m.Name, false, opts.Test, skip); err != nil {
		return nil, err
	}
	// A script's manifest records live in a parsed file; a module's manifest is mod.kg.
	if !m.deferred || !hasMod {
		if err := m.parseReachable(); err != nil {
			return nil, err
		}
		if err := m.scriptManifest(hasMod); err != nil {
			return nil, err
		}
	}
	if err := m.addNative(root, m.Manifest); err != nil {
		return nil, err
	}
	if err := m.addHeaders(root, m.Manifest); err != nil {
		return nil, err
	}
	if !opts.NoLocal {
		if m.local, err = ReadLocal(root); err != nil {
			return nil, err
		}
		if err := m.checkLocalReplace(opts.Policy); err != nil {
			return nil, err
		}
	}
	if !opts.NoDeps {
		lock, err := ReadLock(root)
		if err != nil {
			return nil, err
		}
		enforceLock := true
		if m.ScriptFile != "" {
			scriptLock := filepath.Join(root, filepath.FromSlash(m.ScriptFile)) + ".lock.kg"
			if _, statErr := os.Stat(scriptLock); statErr != nil {
				if len(m.Manifest.Requires) > 0 {
					v := unlockedScriptViolation(m.ScriptFile, filepath.ToSlash(scriptLock))
					if opts.Policy.Dependency == DependencyLocked {
						return nil, releaseError(v)
					}
					m.Violations = append(m.Violations, v)
				}
				enforceLock = false
			} else if lock, err = ReadLockFile(scriptLock); err != nil {
				return nil, err
			}
		}
		if err := m.loadDeps(opts, lock, enforceLock); err != nil {
			return nil, err
		}
	}
	if opts.StdRoot != "" {
		if err := m.indexTree(opts.StdRoot, "std", true, false, nil); err != nil {
			return nil, err
		}
	}
	if m.deferred {
		if m.trySettle(); m.settled == nil {
			m.ensureParsed()
		}
	} else if err := m.parseReachable(); err != nil {
		return nil, err
	} else {
		m.setOrder()
	}
	m.saveMemo()
	if m.loadErr != nil {
		return nil, m.loadErr
	}
	if m.fileOrder != nil {
		m.fileOrder(m.Order)
	}
	return m, nil
}
